function validate(input) {
  const [{ Person = [], Address = [] }] = input;
  const people = new Set(), addresses = new Set();
  for (const [id] of Person) {
    if (id === null) return 'Every person needs a personId.';
    if (people.has(id)) return `personId ${id} appears twice in Person.`;
    people.add(id);
  }
  for (const [id] of Address) {
    if (id === null) return 'Every address needs an addressId.';
    if (addresses.has(id)) return `addressId ${id} appears twice in Address.`;
    addresses.add(id);
  }
  return null;
}

