function generate(rand, size) {
  const names = ['Allen', 'Bob', 'Ana', 'Wang', 'Lee', 'Kim', 'Ravi', 'Sofia'];
  const places = [['New York City', 'New York'], ['Austin', 'Texas'], ['Leetcode', 'California'], ['Boston', 'Massachusetts'], [null, null]];
  const people = size === 'small' ? Math.floor(rand() * 7) : 1500;
  const Person = [], Address = [];
  for (let id = 1; id <= people; id++) Person.push([id, names[Math.floor(rand() * names.length)], names[Math.floor(rand() * names.length)]]);
  // Addresses go to existing people, people who do not exist, or nobody; each person has at most one.
  const owners = [];
  for (let id = 1; id <= people + 3; id++) if (rand() < 0.6) owners.push(id);
  owners.forEach((owner, i) => { const [city, state] = places[Math.floor(rand() * places.length)]; Address.push([i + 1, owner, city, state]); });
  return [{ Person, Address }];
}
